class Point {
    public int X;
    public int Y;
    public Point(int x, int y) { X = x; Y = y; }
    public int Dist() { return Math.Abs(X) + Math.Abs(Y); }
}

static void Main() {
    var p = new Point(3, -4);
    Console.WriteLine(p.X + " " + p.Dist());
    var q = p;
    q.X = 10;
    Console.WriteLine(p.X);
}

